// Fixed regional levels: progression opens harder areas; old areas never chase the player's level.
export const REGION_LEVELS={c3_marsh:[23,25],c3_abbey:[25,27],c3_aerie:[28,29],c3_pass:[17,19],c3_fortress:[17,20],c3_quarry:[18,20],c3_siege:[20,23],c2_road:[11,13],c2_city:[11,13],c2_inn:[12,14],c2_manor:[14,16],forest:[1,2],deep:[2,4],cemetery:[4,6],dungeon:[6,8],lich:[9,9],chapel:[8,10]};
export const QUEST_XP={safe:250,'rabbit-quest':220,'mary-water':180,'hunter-quest':260,'witch-quest':300,'bones-quest':280,'mary-bone-quest':180,'ritual-purified':320,'lich-quest':450,'empty-grave':140,'chapel-quest':500};
const hash=id=>{let h=0;for(const c of String(id))h=(h*31+c.charCodeAt(0))>>>0;return h};
export function enemyLevel(n,zone){if(!n)return 1;if(n.chapterTwo&&Number.isInteger(n.fixedLevel))return n.fixedLevel;if(n.species==='dark-self')return n.level||1;if(n.species==='ghost')return 11;if(n.species==='lich')return 9;if(n.id==='elite'||n.id==='dungeon-ogre')return 9;if(n.id==='bone-keeper')return 7;if(n.species==='hunter'||n.species==='witch')return 5;if(n.species==='troll')return 6;if(zone==='forest'||zone==='home')return n.id?.startsWith('lake-wolf')?2:1;const [min,max]=REGION_LEVELS[zone]||[1,1];const z=n.home?.z;const span={deep:[60,120],cemetery:[43,150],dungeon:[60,96],chapel:[71,95]}[zone];return Number.isFinite(z)&&span?min+Math.min(max-min,Math.max(0,Math.floor((-z-span[0])/span[1]*(max-min+1)))):min+hash(n.id||n.species)%(max-min+1)}
export const eliteEnemy=n=>['abbess','ashwing','sentinel','baron','order-enemy-captain','order-enemy-knight','werewolf','vampire','cultist-warden','ghost','hunter','witch','troll','lich'].includes(n?.species)||['elite','bone-keeper','dungeon-ogre'].includes(n?.id);
export function assignLevels(mobs,zone){if(['admin','trial'].includes(zone))return;for(const n of mobs){n.level=enemyLevel(n,zone);n.elite=eliteEnemy(n)}}
export function levelDamage(attacker,defender){return Math.max(.5,Math.min(1.8,1+(attacker-defender)*.08))}
export function killExperience(p,n){if(!n.chapterTwo&&p.rewards.includes('witch-quest')&&['wolf','hare'].includes(n.species))return 2;const difference=(n.level||1)-p.level;if(difference<=-5)return 0;const base=(n.species==='hare'||n.species==='raven'?12:24)+(n.level||1)*6;return Math.max(1,Math.round(base*(eliteEnemy(n)?2:1)*(difference<0?Math.max(.15,1+difference*.18):Math.min(1.35,1+difference*.08))))}
export function difficultyColor(enemy,player){const d=enemy-player;return d<=-5?'#929aa0':d<0?'#9bd67b':d===0?'#f0e1ba':d===1?'#ffcf69':d===2?'#ff9a54':'#ff6565'}
export function regionLabel(zone){const r=REGION_LEVELS[zone];return r?'Уровни '+r[0]+(r[0]===r[1]?'':'–'+r[1])+(zone==='deep'?' · мини-боссы 5–6':zone==='cemetery'?' · хранитель 7':zone==='dungeon'?' · элита 9':zone==='chapel'?' · звонарь 11':''):''}
export function migrateRegionalProgress(p,required){if(p.levelingVersion===1)return false;let minimum=1;const stage=p.stage||'';if(p.rewards.includes('safe'))minimum=2;if(['forest','carcasses','delivery'].includes(stage))minimum=3;if(p.rewards.includes('rabbit-quest'))minimum=4;if(p.rewards.includes('hunter-quest')||stage.startsWith('witch'))minimum=5;if(p.rewards.includes('witch-quest')||stage.startsWith('bones_'))minimum=6;if(p.rewards.includes('bones-quest')||/^(page_|trial_)/.test(stage))minimum=7;if(p.rewards.includes('ritual-purified')||stage==='ritual_done'||stage==='lich_relic')minimum=8;if(p.rewards.includes('lich-quest')||/^(lich_return|grave_|chapter_complete|chapel_|kingdom_)/.test(stage))minimum=10;const before=p.level;if(before<minimum){const fraction=p.xp/required(before);p.level=minimum;p.xp=Math.floor(fraction*required(minimum));p.pendingLevels=(p.pendingLevels||0)+minimum-before}p.levelingVersion=1;return p.level>before}
